        #[unstable(feature = "f128", issue = "116909")]
        pub const MIN_POSITIVE: f128 = 3.36210314311209350626267781732175260e-4932_f128;
        #[unstable(feature = "f128", issue = "116909")]
        pub const MAX: f128 = 1.18973149535723176508575932662800702e+4932_f128;
