        pub const MIN_EXP: i32 = -16_381;
        #[unstable(feature = "f128", issue = "116909")]
        pub const MAX_EXP: i32 = 16_384;
        #[unstable(feature = "f128", issue = "116909")]
        pub const MIN_10_EXP: i32 = -4_931;
        #[unstable(feature = "f128", issue = "116909")]
        pub const MAX_10_EXP: i32 = 4_932;
        #[allow(clippy::eq_op)] #[unstable(feature = "f128", issue = "116909")]
        pub const NAN: f128 = 0.0_f128 / 0.0_f128;
        #[unstable(feature = "f128", issue = "116909")]
        pub const INFINITY: f128 = 1.0_f128 / 0.0_f128;
        #[unstable(feature = "f128", issue = "116909")]
        pub const NEG_INFINITY: f128 = -1.0_f128 / 0.0_f128;

        pub(crate) const SIGN_MASK: u128 = 0x8000_0000_0000_0000_0000_0000_0000_0000;

        pub(crate) const EXP_MASK: u128 = 0x7fff_0000_0000_0000_0000_0000_0000_0000;

        pub(crate) const MAN_MASK: u128 = 0x0000_ffff_ffff_ffff_ffff_ffff_ffff_ffff;

        const TINY_BITS: u128 = 0x1;

        const NEG_TINY_BITS: u128 = Self::TINY_BITS | Self::SIGN_MASK;
        #[inline] #[must_use] #[unstable(feature = "f128", issue = "116909")] #[allow(clippy::eq_op)]
        pub const fn is_nan(self) -> bool {
            self != self
        }

        #[inline] #[must_use] #[unstable(feature = "f128", issue = "116909")]
        pub const fn is_infinite(self) -> bool {
            (self == f128::INFINITY) | (self == f128::NEG_INFINITY)
        }

        #[inline] #[must_use] #[unstable(feature = "f128", issue = "116909")]
        pub const fn is_finite(self) -> bool {

            self.abs() < Self::INFINITY
        }
        
        #[inline] #[must_use] #[unstable(feature = "f128", issue = "116909")]
        pub const fn is_subnormal(self) -> bool {
            matches!(self.classify(), FpCategory::Subnormal)
        }
        
        #[inline] #[must_use] #[unstable(feature = "f128", issue = "116909")]
        pub const fn is_normal(self) -> bool {
            matches!(self.classify(), FpCategory::Normal)
        }

        #[inline] #[unstable(feature = "f128", issue = "116909")]
        pub const fn classify(self) -> FpCategory {
            let bits = self.to_bits();
            match (bits & Self::MAN_MASK, bits & Self::EXP_MASK) {
                (0, Self::EXP_MASK) => FpCategory::Infinite,
                (_, Self::EXP_MASK) => FpCategory::Nan,
                (0, 0) => FpCategory::Zero,
                (_, 0) => FpCategory::Subnormal,
                _ => FpCategory::Normal,
            }
        }

        #[inline] #[must_use] #[unstable(feature = "f128", issue = "116909")]
        pub const fn is_sign_positive(self) -> bool {
            !self.is_sign_negative()
        }

        #[inline] #[must_use] #[unstable(feature = "f128", issue = "116909")]
        pub const fn is_sign_negative(self) -> bool {
    
            (self.to_bits() & (1 << 127)) != 0
        }

        #[inline] #[doc(alias = "nextUp")] #[unstable(feature = "f128", issue = "116909")]
        pub const fn next_up(self) -> Self {
    
            let bits = self.to_bits();
            if self.is_nan() || bits == Self::INFINITY.to_bits() {
                return self;
            }
            let abs = bits & !Self::SIGN_MASK;
            let next_bits = if abs == 0 {
                Self::TINY_BITS
            } else if bits == abs {
                bits + 1
            } else {
                bits - 1
            };
            Self::from_bits(next_bits)
        }

        #[inline] #[doc(alias = "nextDown")] #[unstable(feature = "f128", issue = "116909")]
        pub const fn next_down(self) -> Self {
    
            let bits = self.to_bits();
            if self.is_nan() || bits == Self::NEG_INFINITY.to_bits() {
                return self;
            }
            let abs = bits & !Self::SIGN_MASK;
            let next_bits = if abs == 0 {
                Self::NEG_TINY_BITS
            } else if bits == abs {
                bits - 1
            } else {
                bits + 1
            };
            Self::from_bits(next_bits)
        }
        
