        #[must_use = "method returns a new number and does not mutate the original value"] #[stable(feature = "rust1", since = "1.0.0")] #[inline] pub const fn signum(self) -> f64 {
            if self.is_nan() { Self::NAN } else { 1.0_f64.copysign(self) }
        }

