    impl usize {
        #[inline]
        pub(crate) const fn repeat_u8(x: u8) -> usize {
            usize::from_ne_bytes([x; size_of::<usize>()])
        }

        #[inline]
        pub(crate) const fn repeat_u16(x: u16) -> usize {
            let mut r = 0usize;
            let mut i = 0;
            while i < size_of::<usize>() {

                r = r.wrapping_shl(16) | (x as usize);
                i += 2;
            }
            r
        }
    }

