    #[doc(alias = "memcpy")] #[stable(feature = "rust1", since = "1.0.0")] #[inline(always)] #[cfg_attr(miri, track_caller)]
    pub const unsafe fn copy_nonoverlapping<T>(src: *const T, dst: *mut T, count: usize) {
        ub_checks::assert_unsafe_precondition!(
            check_language_ub,
            "ptr::copy_nonoverlapping requires that both pointer arguments are aligned and non-null \
            and the specified memory ranges do not overlap",
            (
                src: *const () = src as *const (),
                dst: *mut () = dst as *mut (),
                size: usize = size_of::<T>(),
                align: usize = align_of::<T>(),
                count: usize = count,
            ) => {
                let zero_size = count == 0 || size == 0;
                ub_checks::maybe_is_aligned_and_not_null(src, align, zero_size)
                    && ub_checks::maybe_is_aligned_and_not_null(dst, align, zero_size)
                    && ub_checks::maybe_is_nonoverlapping(src, dst, size, count)
            }
        );

        unsafe { crate::intrinsics::copy_nonoverlapping(src, dst, count) }
    }
    
    #[doc(alias = "memmove")] #[stable(feature = "rust1", since = "1.0.0")] #[inline(always)] #[cfg_attr(miri, track_caller)]
    pub const unsafe fn copy<T>(src: *const T, dst: *mut T, count: usize) {

        unsafe {
            ub_checks::assert_unsafe_precondition!(
                check_language_ub,
                "ptr::copy requires that both pointer arguments are aligned and non-null",
                (
                    src: *const () = src as *const (),
                    dst: *mut () = dst as *mut (),
                    align: usize = align_of::<T>(),
                    zero_size: bool = T::IS_ZST || count == 0,
                ) =>
                ub_checks::maybe_is_aligned_and_not_null(src, align, zero_size)
                    && ub_checks::maybe_is_aligned_and_not_null(dst, align, zero_size)
            );
            crate::intrinsics::copy(src, dst, count)
        }
    }
    
    #[doc(alias = "memset")] #[stable(feature = "rust1", since = "1.0.0")] #[inline(always)] #[cfg_attr(miri, track_caller)]
    pub const unsafe fn write_bytes<T>(dst: *mut T, val: u8, count: usize) {

        unsafe {
            ub_checks::assert_unsafe_precondition!(
                check_language_ub,
                "ptr::write_bytes requires that the destination pointer is aligned and non-null",
                (
                    addr: *const () = dst as *const (),
                    align: usize = align_of::<T>(),
                    zero_size: bool = T::IS_ZST || count == 0,
                ) => ub_checks::maybe_is_aligned_and_not_null(addr, align, zero_size)
            );
            crate::intrinsics::write_bytes(dst, val, count)
        }
    }
    
