        macro_rules! impl_try_from_unbounded
        {
            ($source:ty => $($target:ty),+) => 
            {$(
                #[stable(feature = "try_from", since = "1.34.0")]
                #[rustc_const_unstable(feature = "const_convert", issue = "143773")]
                impl const TryFrom<$source> for $target
                {
                    type Error = TryFromIntError;
                    #[inline] fn try_from(value: $source) -> Result<Self, Self::Error> { Ok(value as Self) }
                }
            )*}
        }
        
        macro_rules! impl_try_from_lower_bounded
        {
            ($source:ty => $($target:ty),+) => 
            {$(
                #[stable(feature = "try_from", since = "1.34.0")] #[rustc_const_unstable(feature = "const_convert", issue = "143773")]
                impl const TryFrom<$source> for $target
                {
                    type Error = TryFromIntError;
                    #[inline] fn try_from(u: $source) -> Result<Self, Self::Error> { if u >= 0 { Ok(u as Self) } else { Err(TryFromIntError(())) } }
                }
            )*}
        }
        
        macro_rules! impl_try_from_upper_bounded
        {
            ($source:ty => $($target:ty),+) =>
            {$(
                #[stable(feature = "try_from", since = "1.34.0")] #[rustc_const_unstable(feature = "const_convert", issue = "143773")]
                impl const TryFrom<$source> for $target
                {
                    type Error = TryFromIntError;
                    #[inline] fn try_from(u: $source) -> Result<Self, Self::Error> { if u > (Self::MAX as $source) { Err(TryFromIntError(())) } else { Ok(u as Self) } }
                }
            )*}
        }
        
        macro_rules! impl_try_from_both_bounded 
        {
            ($source:ty => $($target:ty),+) => 
            {$(
                #[stable(feature = "try_from", since = "1.34.0")] #[rustc_const_unstable(feature = "const_convert", issue = "143773")]
                impl const TryFrom<$source> for $target
                {
                    type Error = TryFromIntError;
                    #[inline] fn try_from(u: $source) -> Result<Self, Self::Error>
                    {
                        let min = Self::MIN as $source;
                        let max = Self::MAX as $source;
                        if u < min || u > max { Err(TryFromIntError(())) } else { Ok(u as Self) }
                    }
                }
            )*}
        }

        macro_rules! rev
        {
            ($mac:ident, $source:ty => $($target:ty),+) => 
            {$(
                $mac!($target => $source);
            )*}
        }
        
