    #[stable(feature = "rust1", since = "1.0.0")]
    
    #[allow(multiple_supertrait_upcastable)]
    pub trait Error: Debug + Display {
        
    
        #[stable(feature = "error_source", since = "1.30.0")]
        fn source(&self) -> Option<&(dyn Error + 'static)> {
            None
        }

        #[doc(hidden)] #[unstable(
            feature = "error_type_id",
            reason = "this is memory-unsafe to override in user code",
            issue = "60784"
        )]
        fn type_id(&self, _: private::Internal) -> TypeId where
            Self: 'static,
        {
            TypeId::of::<Self>()
        }
        
        #[stable(feature = "rust1", since = "1.0.0")] #[deprecated(since = "1.42.0", note = "use the Display impl or to_string()")]
        fn description(&self) -> &str {
            "description() is deprecated; use Display"
        }
        
        #[stable(feature = "rust1", since = "1.0.0")] #[deprecated(
            since = "1.33.0",
            note = "replaced by Error::source, which can support downcasting"
        )] #[allow(missing_docs)]
        fn cause(&self) -> Option<&dyn Error> {
            self.source()
        }
        
        #[unstable(feature = "error_generic_member_access", issue = "99301")] #[allow(unused_variables)]
        fn provide<'a>(&'a self, request: &mut Request<'a>) {}
    }
    mod private {

        #[unstable(feature = "error_type_id", issue = "60784")] #[derive(Debug)]
        pub struct Internal;
    }
    #[unstable(feature = "never_type", issue = "35121")]
    impl Error for ! {}

    impl dyn Error + 'static {
        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn is<T: Error + 'static>(&self) -> bool {

            let t = TypeId::of::<T>();

            let concrete = self.type_id(private::Internal);

            t == concrete
        }

        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn downcast_ref<T: Error + 'static>(&self) -> Option<&T> {
            if self.is::<T>() { unsafe { Some(&*(self as *const dyn Error as *const T)) } } else {
                None
            }
        }

        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn downcast_mut<T: Error + 'static>(&mut self) -> Option<&mut T> {
            if self.is::<T>() { unsafe { Some(&mut *(self as *mut dyn Error as *mut T)) } } else {
                None
            }
        }
    }
    
    impl dyn Error + 'static + Send {
        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn is<T: Error + 'static>(&self) -> bool {
            <dyn Error + 'static>::is::<T>(self)
        }

        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn downcast_ref<T: Error + 'static>(&self) -> Option<&T> {
            <dyn Error + 'static>::downcast_ref::<T>(self)
        }

        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn downcast_mut<T: Error + 'static>(&mut self) -> Option<&mut T> {
            <dyn Error + 'static>::downcast_mut::<T>(self)
        }
    }
    
    impl dyn Error + 'static + Send + Sync {
        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn is<T: Error + 'static>(&self) -> bool {
            <dyn Error + 'static>::is::<T>(self)
        }

        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn downcast_ref<T: Error + 'static>(&self) -> Option<&T> {
            <dyn Error + 'static>::downcast_ref::<T>(self)
        }

        #[stable(feature = "error_downcast", since = "1.3.0")] #[inline] pub fn downcast_mut<T: Error + 'static>(&mut self) -> Option<&mut T> {
            <dyn Error + 'static>::downcast_mut::<T>(self)
        }
    }
    
    impl dyn Error {
    
        #[unstable(feature = "error_iter", issue = "58520")] #[inline] pub fn sources(&self) -> Source<'_> {
    
            Source { current: Some(self) }
        }
    }
    
    #[unstable(feature = "error_generic_member_access", issue = "99301")]
    pub fn request_value<'a, T>(err: &'a (impl Error + ?Sized)) -> Option<T>
    where
        T: 'static,
    {
        request_by_type_tag::<'a, tags::Value<T>>(err)
    }
    
    #[unstable(feature = "error_generic_member_access", issue = "99301")]
    pub fn request_ref<'a, T>(err: &'a (impl Error + ?Sized)) -> Option<&'a T>
    where
        T: 'static + ?Sized,
    {
        request_by_type_tag::<'a, tags::Ref<tags::MaybeSizedValue<T>>>(err)
    }

    fn request_by_type_tag<'a, I>(err: &'a (impl Error + ?Sized)) -> Option<I::Reified>
    where
        I: tags::Type<'a>,
    {
        let mut tagged = Tagged { tag_id: TypeId::of::<I>(), value: TaggedOption::<'a, I>(None) };
        err.provide(tagged.as_request());
        tagged.value.0
    }
    
    #[unstable(feature = "error_generic_member_access", issue = "99301")] #[repr(transparent)]
    pub struct Request<'a>(Tagged<dyn Erased<'a> + 'a>);
    impl<'a> Request<'a> {
        
    
        #[unstable(feature = "error_generic_member_access", issue = "99301")]
        pub fn provide_value<T>(&mut self, value: T) -> &mut Self where
            T: 'static,
        {
            self.provide::<tags::Value<T>>(value)
        }

        #[unstable(feature = "error_generic_member_access", issue = "99301")]
        pub fn provide_value_with<T>(&mut self, fulfil: impl FnOnce() -> T) -> &mut Self where
            T: 'static,
        {
            self.provide_with::<tags::Value<T>>(fulfil)
        }

        #[unstable(feature = "error_generic_member_access", issue = "99301")]
        pub fn provide_ref<T: ?Sized + 'static>(&mut self, value: &'a T) -> &mut Self {
            self.provide::<tags::Ref<tags::MaybeSizedValue<T>>>(value)
        }

        #[unstable(feature = "error_generic_member_access", issue = "99301")]
        pub fn provide_ref_with<T: ?Sized + 'static>(
            &mut self,
            fulfil: impl FnOnce() -> &'a T,
        ) -> &mut Self {
            self.provide_with::<tags::Ref<tags::MaybeSizedValue<T>>>(fulfil)
        }

        fn provide<I>(&mut self, value: I::Reified) -> &mut Self where
            I: tags::Type<'a>,
        {
            if let Some(res @ TaggedOption(None)) = self.0.downcast_mut::<I>() {
                res.0 = Some(value);
            }
            self
        }

        fn provide_with<I>(&mut self, fulfil: impl FnOnce() -> I::Reified) -> &mut Self where
            I: tags::Type<'a>,
        {
            if let Some(res @ TaggedOption(None)) = self.0.downcast_mut::<I>() {
                res.0 = Some(fulfil());
            }
            self
        }
        
        
        #[unstable(feature = "error_generic_member_access", issue = "99301")]
        pub fn would_be_satisfied_by_value_of<T>(&self) -> bool where
            T: 'static,
        {
            self.would_be_satisfied_by::<tags::Value<T>>()
        }
    
        
        

        #[unstable(feature = "error_generic_member_access", issue = "99301")]
        pub fn would_be_satisfied_by_ref_of<T>(&self) -> bool where
            T: ?Sized + 'static,
        {
            self.would_be_satisfied_by::<tags::Ref<tags::MaybeSizedValue<T>>>()
        }
        fn would_be_satisfied_by<I>(&self) -> bool where
            I: tags::Type<'a>,
        {
            matches!(self.0.downcast::<I>(), Some(TaggedOption(None)))
        }
    }
    #[unstable(feature = "error_generic_member_access", issue = "99301")]
    impl<'a> Debug for Request<'a> {
        fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
            f.debug_struct("Request").finish_non_exhaustive()
        }
    }
    
    pub(crate) mod tags {
    
        use crate::marker::PhantomData;

        pub(crate) trait Type<'a>: Sized + 'static {

            type Reified: 'a;
        }

        pub(crate) trait MaybeSizedType<'a>: Sized + 'static {
            type Reified: 'a + ?Sized;
        }
        
        impl<'a, T: Type<'a>> MaybeSizedType<'a> for T {
            type Reified = T::Reified;
        }

        #[derive(Debug)]
        pub(crate) struct Value<T: 'static>(PhantomData<T>);
        impl<'a, T: 'static> Type<'a> for Value<T> {
            type Reified = T;
        }

        #[derive(Debug)]
        pub(crate) struct MaybeSizedValue<T: ?Sized + 'static>(PhantomData<T>);
        impl<'a, T: ?Sized + 'static> MaybeSizedType<'a> for MaybeSizedValue<T> {
            type Reified = T;
        }

        #[derive(Debug)]
        pub(crate) struct Ref<I>(PhantomData<I>);
        impl<'a, I: MaybeSizedType<'a>> Type<'a> for Ref<I> {
            type Reified = &'a I::Reified;
        }
    }

        #[repr(transparent)]
    pub(crate) struct TaggedOption<'a, I: tags::Type<'a>>(pub Option<I::Reified>);
    impl<'a, I: tags::Type<'a>> Tagged<TaggedOption<'a, I>> {
        pub(crate) fn as_request(&mut self) -> &mut Request<'a> {
            let erased = self as &mut Tagged<dyn Erased<'a> + 'a>;

            unsafe { &mut *(erased as *mut Tagged<dyn Erased<'a>> as *mut Request<'a>) }
        }
    }
    
    unsafe trait Erased<'a>: 'a {}
    unsafe impl<'a, I: tags::Type<'a>> Erased<'a> for TaggedOption<'a, I> {}
    struct Tagged<E: ?Sized> {
        tag_id: TypeId,
        value: E,
    }
    
    impl<'a> Tagged<dyn Erased<'a> + 'a> {

        #[inline] fn downcast<I>(&self) -> Option<&TaggedOption<'a, I>> where
            I: tags::Type<'a>,
        {
            if self.tag_id == TypeId::of::<I>() {

                Some(&unsafe { &*(self as *const Self).cast::<Tagged<TaggedOption<'a, I>>>() }.value)
            } else {
                None
            }
        }

        #[inline] fn downcast_mut<I>(&mut self) -> Option<&mut TaggedOption<'a, I>> where
            I: tags::Type<'a>,
        {
            if self.tag_id == TypeId::of::<I>() {
                Some(

                    &mut unsafe { &mut *(self as *mut Self).cast::<Tagged<TaggedOption<'a, I>>>() }
                        .value,
                )
            } else {
                None
            }
        }
    }

        #[unstable(feature = "error_iter", issue = "58520")] #[derive(Clone, Debug)]
    pub struct Source<'a> {
        current: Option<&'a (dyn Error + 'static)>,
    }
    #[unstable(feature = "error_iter", issue = "58520")]
    impl<'a> Iterator for Source<'a> {
        type Item = &'a (dyn Error + 'static);
        fn next(&mut self) -> Option<Self::Item> {
            let current = self.current;
            self.current = self.current.and_then(Error::source);
            current
        }
        fn size_hint(&self) -> (usize, Option<usize>) {
            if self.current.is_some() { (1, None) } else { (0, Some(0)) }
        }
    }
