    #[stable(feature = "rust1", since = "1.0.0")]
    pub struct RefCell<T: ?Sized> {
        borrow: Cell<BorrowCounter>,
    
        #[cfg(feature = "debug_refcell")]
        borrowed_at: Cell<Option<&'static crate::panic::Location<'static>>>,
        value: UnsafeCell<T>,
    }

    #[stable(feature = "try_borrow", since = "1.13.0")] #[non_exhaustive] #[derive(Debug)]
    pub struct BorrowError {
        #[cfg(feature = "debug_refcell")]
        location: &'static crate::panic::Location<'static>,
    }
    #[stable(feature = "try_borrow", since = "1.13.0")]
    impl Display for BorrowError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            #[cfg(feature = "debug_refcell")]
            let res = write!(
                f,
                "RefCell already mutably borrowed; a previous borrow was at {}",
                self.location
            );
            #[cfg(not(feature = "debug_refcell"))]
            let res = Display::fmt("RefCell already mutably borrowed", f);
            res
        }
    }

    #[stable(feature = "try_borrow", since = "1.13.0")] #[non_exhaustive] #[derive(Debug)]
    pub struct BorrowMutError {
        #[cfg(feature = "debug_refcell")]
        location: &'static crate::panic::Location<'static>,
    }
    #[stable(feature = "try_borrow", since = "1.13.0")]
    impl Display for BorrowMutError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            #[cfg(feature = "debug_refcell")]
            let res = write!(f, "RefCell already borrowed; a previous borrow was at {}", self.location);
            #[cfg(not(feature = "debug_refcell"))]
            let res = Display::fmt("RefCell already borrowed", f);
            res
        }
    }

    #[cfg_attr(not(panic = "immediate-abort"), inline(never))] #[track_caller] #[cold]
    const fn panic_already_borrowed(err: BorrowMutError) -> ! {
        const_panic!(
            "RefCell already borrowed",
            "{err}",
            err: BorrowMutError = err,
        )
    }

    #[cfg_attr(not(panic = "immediate-abort"), inline(never))] #[track_caller] #[cold]
    const fn panic_already_mutably_borrowed(err: BorrowError) -> ! {
        const_panic!(
            "RefCell already mutably borrowed",
            "{err}",
            err: BorrowError = err,
        )
    }
    
    
    type BorrowCounter = isize;
    const UNUSED: BorrowCounter = 0;
    #[inline(always)]
    const fn is_writing(x: BorrowCounter) -> bool {
        x < UNUSED
    }
    #[inline(always)]
    const fn is_reading(x: BorrowCounter) -> bool {
        x > UNUSED
    }
    
    impl<T> RefCell<T> {
        

        #[stable(feature = "rust1", since = "1.0.0")] #[inline] pub const fn new(value: T) -> RefCell<T> {
            RefCell {
                value: UnsafeCell::new(value),
                borrow: Cell::new(UNUSED),
                #[cfg(feature = "debug_refcell")]
                borrowed_at: Cell::new(None),
            }
        }

        #[stable(feature = "rust1", since = "1.0.0")]
        #[inline] pub const fn into_inner(self) -> T {

            self.value.into_inner()
        }
        
        #[inline] #[stable(feature = "refcell_replace", since = "1.24.0")] #[track_caller]
    
        pub const fn replace(&self, t: T) -> T {
            mem::replace(&mut self.borrow_mut(), t)
        }

        #[inline] #[stable(feature = "refcell_replace_swap", since = "1.35.0")] #[track_caller]

        pub fn replace_with<F: FnOnce(&mut T) -> T>(&self, f: F) -> T {
            let mut_borrow = &mut *self.borrow_mut();
            let replacement = f(mut_borrow);
            mem::replace(mut_borrow, replacement)
        }

        #[inline] #[stable(feature = "refcell_swap", since = "1.24.0")]
    
        pub const fn swap(&self, other: &Self) {
            mem::swap(&mut *self.borrow_mut(), &mut *other.borrow_mut())
        }
    }
    
    impl<T: ?Sized> RefCell<T> {
        
    
        

        #[stable(feature = "rust1", since = "1.0.0")] #[inline] #[track_caller]
    
        pub const fn borrow(&self) -> Ref<'_, T> {
            match self.try_borrow() {
                Ok(b) => b,
                Err(err) => panic_already_mutably_borrowed(err),
            }
        }
        
        #[stable(feature = "try_borrow", since = "1.13.0")] #[inline] #[cfg_attr(feature = "debug_refcell", track_caller)]
    
        pub const fn try_borrow(&self) -> Result<Ref<'_, T>, BorrowError> {
            match BorrowRef::new(&self.borrow) {
                Some(b) => {
                    #[cfg(feature = "debug_refcell")]
                    {

                        if b.borrow.get() == 1 {
                            self.borrowed_at.replace(Some(crate::panic::Location::caller()));
                        }
                    }

                    let value = unsafe { NonNull::new_unchecked(self.value.get()) };
                    Ok(Ref { value, borrow: b })
                }
                None => Err(BorrowError {

                    #[cfg(feature = "debug_refcell")]
                    location: self.borrowed_at.get().unwrap(),
                }),
            }
        }
        
        #[stable(feature = "rust1", since = "1.0.0")] #[inline] #[track_caller]
    
        pub const fn borrow_mut(&self) -> RefMut<'_, T> {
            match self.try_borrow_mut() {
                Ok(b) => b,
                Err(err) => panic_already_borrowed(err),
            }
        }
        
        #[stable(feature = "try_borrow", since = "1.13.0")] #[inline] #[cfg_attr(feature = "debug_refcell", track_caller)]
    
        pub const fn try_borrow_mut(&self) -> Result<RefMut<'_, T>, BorrowMutError> {
            match BorrowRefMut::new(&self.borrow) {
                Some(b) => {
                    #[cfg(feature = "debug_refcell")]
                    {
                        self.borrowed_at.replace(Some(crate::panic::Location::caller()));
                    }

                    let value = unsafe { NonNull::new_unchecked(self.value.get()) };
                    Ok(RefMut { value, borrow: b, marker: PhantomData })
                }
                None => Err(BorrowMutError {

                    #[cfg(feature = "debug_refcell")]
                    location: self.borrowed_at.get().unwrap(),
                }),
            }
        }

        #[inline] #[stable(feature = "cell_as_ptr", since = "1.12.0")]
    
        pub const fn as_ptr(&self) -> *mut T {
            self.value.get()
        }
    
        
        #[inline] #[stable(feature = "cell_get_mut", since = "1.11.0")]
        pub const fn get_mut(&mut self) -> &mut T {
            self.value.get_mut()
        }
        
        #[unstable(feature = "cell_leak", issue = "69099")]
        pub const fn undo_leak(&mut self) -> &mut T {
            *self.borrow.get_mut() = UNUSED;
            self.get_mut()
        }
        
        #[stable(feature = "borrow_state", since = "1.37.0")] #[inline]

        pub const unsafe fn try_borrow_unguarded(&self) -> Result<&T, BorrowError> {
            if !is_writing(self.borrow.get()) {
    
                Ok(unsafe { &*self.value.get() })
            } else {
                Err(BorrowError {

                    #[cfg(feature = "debug_refcell")]
                    location: self.borrowed_at.get().unwrap(),
                })
            }
        }
    }
    
