    #[stable(feature = "fmt_flags_align", since = "1.28.0")] #[derive(Copy, Clone, Debug, PartialEq, Eq)]
    pub enum Alignment {
        #[stable(feature = "fmt_flags_align", since = "1.28.0")]
        Left,
        #[stable(feature = "fmt_flags_align", since = "1.28.0")]
        Right,
        #[stable(feature = "fmt_flags_align", since = "1.28.0")]
        Center,
    }
