    impl<H> Eq for BuildHasherDefault<H> {}
    mod impls {
        use super::*;
        use crate::slice;
        macro_rules! impl_write {
            ($(($ty:ident, $meth:ident),)*) => {$(
                #[stable(feature = "rust1", since = "1.0.0")]
                impl Hash for $ty {
                    #[inline] fn hash<H: Hasher>(&self, state: &mut H) {
                        state.$meth(*self)
                    }
                    #[inline] fn hash_slice<H: Hasher>(data: &[$ty], state: &mut H) {
                        let newlen = size_of_val(data);
                        let ptr = data.as_ptr() as *const u8;
                    state.write(unsafe { slice::from_raw_parts(ptr, newlen) })
                    }
                }
            )*}
        }

        impl_write! {
            (u8, write_u8),
            (u16, write_u16),
            (u32, write_u32),
            (u64, write_u64),
            (usize, write_usize),
            (i8, write_i8),
            (i16, write_i16),
            (i32, write_i32),
            (i64, write_i64),
            (isize, write_isize),
            (u128, write_u128),
            (i128, write_i128),
        }
        
        #[stable(feature = "rust1", since = "1.0.0")]
        impl Hash for bool {
            #[inline]
            fn hash<H: Hasher>(&self, state: &mut H) {
                state.write_u8(*self as u8)
            }
        }
        
        #[stable(feature = "rust1", since = "1.0.0")]
        impl Hash for char {
            #[inline]
            fn hash<H: Hasher>(&self, state: &mut H) {
                state.write_u32(*self as u32)
            }
        }
        
        #[stable(feature = "rust1", since = "1.0.0")]
        impl Hash for str {
            #[inline]
            fn hash<H: Hasher>(&self, state: &mut H) {
                state.write_str(self);
            }
        }
        
        #[stable(feature = "never_hash", since = "1.29.0")]
        impl Hash for ! {
            #[inline]
            fn hash<H: Hasher>(&self, _: &mut H) {
                *self
            }
        }

        macro_rules! impl_hash_tuple {
            () => (
                #[stable(feature = "rust1", since = "1.0.0")]
                impl Hash for () {
                    #[inline] fn hash<H: Hasher>(&self, _state: &mut H) {}
                }
            );
            ( $($name:ident)+) => (
                maybe_tuple_doc! {
                    $($name)+ @
                    #[stable(feature = "rust1", since = "1.0.0")]
                    impl<$($name: Hash),+> Hash for ($($name,)+) {
                        #[allow(non_snake_case)]
                        #[inline]
                        fn hash<S: Hasher>(&self, state: &mut S) {
                            let ($(ref $name,)+) = *self;
                            $($name.hash(state);)+
                        }
                    }
                }
            );
        }

        macro_rules! maybe_tuple_doc {
            ($a:ident @ #[$meta:meta] $item:item) => {
                #[doc(fake_variadic)]
                #[doc = "This trait is implemented for tuples up to twelve items long."]
                #[$meta]
                $item
            };
            ($a:ident $($rest_a:ident)+ @ #[$meta:meta] $item:item) => {
                #[doc(hidden)]
                #[$meta]
                $item
            };
        }

        impl_hash_tuple! {}

        impl_hash_tuple! { T }

        impl_hash_tuple! { T B }

        impl_hash_tuple! { T B C }

        impl_hash_tuple! { T B C D }

        impl_hash_tuple! { T B C D E }

        impl_hash_tuple! { T B C D E F }

        impl_hash_tuple! { T B C D E F G }

        impl_hash_tuple! { T B C D E F G H }

        impl_hash_tuple! { T B C D E F G H I }

        impl_hash_tuple! { T B C D E F G H I J }

        impl_hash_tuple! { T B C D E F G H I J K }

        impl_hash_tuple! { T B C D E F G H I J K L }
        
        #[stable(feature = "rust1", since = "1.0.0")]
        impl<T: Hash> Hash for [T] {
            #[inline]
            fn hash<H: Hasher>(&self, state: &mut H) {
                state.write_length_prefix(self.len());
                Hash::hash_slice(self, state)
            }
        }
        
        #[stable(feature = "rust1", since = "1.0.0")]
        impl<T: ?Sized + marker::PointeeSized + Hash> Hash for &T {
            #[inline]
            fn hash<H: Hasher>(&self, state: &mut H) {
                (**self).hash(state);
            }
        }
        
        #[stable(feature = "rust1", since = "1.0.0")]
        impl<T: ?Sized + marker::PointeeSized + Hash> Hash for &mut T {
            #[inline]
            fn hash<H: Hasher>(&self, state: &mut H) {
                (**self).hash(state);
            }
        }
        
        #[stable(feature = "rust1", since = "1.0.0")]
        impl<T: ?Sized + marker::PointeeSized> Hash for *const T {
            #[inline]
            fn hash<H: Hasher>(&self, state: &mut H) {
                let (address, metadata) = self.to_raw_parts();
                state.write_usize(address.addr());
                metadata.hash(state);
            }
        }
        
        #[stable(feature = "rust1", since = "1.0.0")]
        impl<T: ?Sized + marker::PointeeSized> Hash for *mut T {
            #[inline]
            fn hash<H: Hasher>(&self, state: &mut H) {
                let (address, metadata) = self.to_raw_parts();
                state.write_usize(address.addr());
                metadata.hash(state);
            }
        }
    }
