        #[stable(feature = "rust1", since = "1.0.0")] #[must_use]
        pub fn starts_with(&self, needle: &[T]) -> bool where
            T: PartialEq,
        {
            let n = needle.len();
            self.len() >= n && needle == &self[..n]
        }

        #[stable(feature = "rust1", since = "1.0.0")] #[must_use]
        pub fn ends_with(&self, needle: &[T]) -> bool where
            T: PartialEq,
        {
            let (m, n) = (self.len(), needle.len());
            m >= n && needle == &self[m - n..]
        }

        #[must_use = "returns the subslice without modifying the original"] #[stable(feature = "slice_strip", since = "1.51.0")]
        pub fn strip_prefix<P: SlicePattern<Item = T> + ?Sized>(&self, prefix: &P) -> Option<&[T]> where
            T: PartialEq,
        {

            let prefix = prefix.as_slice();
            let n = prefix.len();
            if n <= self.len() {
                let (head, tail) = self.split_at(n);
                if head == prefix {
                    return Some(tail);
                }
            }
            None
        }

        #[must_use = "returns the subslice without modifying the original"] #[stable(feature = "slice_strip", since = "1.51.0")]
        pub fn strip_suffix<P: SlicePattern<Item = T> + ?Sized>(&self, suffix: &P) -> Option<&[T]> where
            T: PartialEq,
        {

            let suffix = suffix.as_slice();
            let (len, n) = (self.len(), suffix.len());
            if n <= len {
                let (head, tail) = self.split_at(len - n);
                if tail == suffix {
                    return Some(head);
                }
            }
            None
        }

        #[must_use = "returns the subslice without modifying the original"] #[unstable(feature = "strip_circumfix", issue = "147946")]
        pub fn strip_circumfix<S, P>(&self, prefix: &P, suffix: &S) -> Option<&[T]> where
            T: PartialEq,
            S: SlicePattern<Item = T> + ?Sized,
            P: SlicePattern<Item = T> + ?Sized,
        {
            self.strip_prefix(prefix)?.strip_suffix(suffix)
        }
        
        #[must_use = "returns the subslice without modifying the original"] #[unstable(feature = "trim_prefix_suffix", issue = "142312")]
        pub fn trim_prefix<P: SlicePattern<Item = T> + ?Sized>(&self, prefix: &P) -> &[T] where
            T: PartialEq,
        {

            let prefix = prefix.as_slice();
            let n = prefix.len();
            if n <= self.len() {
                let (head, tail) = self.split_at(n);
                if head == prefix {
                    return tail;
                }
            }
            self
        }
        
        #[must_use = "returns the subslice without modifying the original"] #[unstable(feature = "trim_prefix_suffix", issue = "142312")]
        pub fn trim_suffix<P: SlicePattern<Item = T> + ?Sized>(&self, suffix: &P) -> &[T] where
            T: PartialEq,
        {

            let suffix = suffix.as_slice();
            let (len, n) = (self.len(), suffix.len());
            if n <= len {
                let (head, tail) = self.split_at(len - n);
                if tail == suffix {
                    return head;
                }
            }
            self
        }
    
        
        #[stable(feature = "rust1", since = "1.0.0")]
        pub fn binary_search(&self, x: &T) -> Result<usize, usize> where
            T: Ord,
        {
            self.binary_search_by(|p| p.cmp(x))
        }
        
        #[stable(feature = "rust1", since = "1.0.0")] #[inline] pub fn binary_search_by<'a, F>(&'a self, mut f: F) -> Result<usize, usize> where
            F: FnMut(&'a T) -> Ordering,
        {
            let mut size = self.len();
            if size == 0 {
                return Err(0);
            }
            let mut base = 0usize;
        while size > 1 {
                let half = size / 2;
                let mid = base + half;

                let cmp = f(unsafe { self.get_unchecked(mid) });

                base = hint::select_unpredictable(cmp == Greater, base, mid);
            size -= half;
            }

            let cmp = f(unsafe { self.get_unchecked(base) });
            if cmp == Equal {

                unsafe { hint::assert_unchecked(base < self.len()) };
                Ok(base)
            } else {
                let result = base + (cmp == Less) as usize;

                unsafe { hint::assert_unchecked(result <= self.len()) };
                Err(result)
            }
        }
    
        #[allow(rustdoc::broken_intra_doc_links)] #[stable(feature = "slice_binary_search_by_key", since = "1.10.0")] #[inline] pub fn binary_search_by_key<'a, B, F>(&'a self, b: &B, mut f: F) -> Result<usize, usize> where
            F: FnMut(&'a T) -> B,
            B: Ord,
        {
            self.binary_search_by(|k| f(k).cmp(b))
        }
    
    
