        pub const fn swap_with_slice(&mut self, other: &mut [T]) {
            assert!(self.len() == other.len(), "destination and source slices have different lengths");

            unsafe {
                ptr::swap_nonoverlapping(self.as_mut_ptr(), other.as_mut_ptr(), self.len());
            }
        }

        fn align_to_offsets<U>(&self) -> (usize, usize) {
    
    
    
            const fn gcd(a: usize, b: usize) -> usize {
                if b == 0 { a } else { gcd(b, a % b) }
            }

            let gcd: usize = const { gcd(size_of::<T>(), size_of::<U>()) };
            let ts: usize = size_of::<U>() / gcd;
            let us: usize = size_of::<T>() / gcd;

            let us_len = self.len() / ts * us;

            let ts_len = self.len() % ts;
            (us_len, ts_len)
        }
        
        #[stable(feature = "slice_align_to", since = "1.30.0")] #[must_use]
        pub unsafe fn align_to<U>(&self) -> (&[T], &[U], &[T]) {

            if U::IS_ZST || T::IS_ZST {

                return (self, &[], &[]);
            }

            let ptr = self.as_ptr();

            let offset = unsafe { crate::ptr::align_offset(ptr, align_of::<U>()) };
            if offset > self.len() {
                (self, &[], &[])
            } else {
                let (left, rest) = self.split_at(offset);
                let (us_len, ts_len) = rest.align_to_offsets::<U>();

                #[cfg(miri)]
                crate::intrinsics::miri_promise_symbolic_alignment(
                    rest.as_ptr().cast(),
                    align_of::<U>(),
                );

                unsafe {
                    (
                        left,
                        from_raw_parts(rest.as_ptr() as *const U, us_len),
                        from_raw_parts(rest.as_ptr().add(rest.len() - ts_len), ts_len),
                    )
                }
            }
        }
        
        #[stable(feature = "slice_align_to", since = "1.30.0")] #[must_use]
        pub unsafe fn align_to_mut<U>(&mut self) -> (&mut [T], &mut [U], &mut [T]) {

            if U::IS_ZST || T::IS_ZST {

                return (self, &mut [], &mut []);
            }

            let ptr = self.as_ptr();

            let offset = unsafe { crate::ptr::align_offset(ptr, align_of::<U>()) };
            if offset > self.len() {
                (self, &mut [], &mut [])
            } else {
                let (left, rest) = self.split_at_mut(offset);
                let (us_len, ts_len) = rest.align_to_offsets::<U>();
                let rest_len = rest.len();
                let mut_ptr = rest.as_mut_ptr();

                #[cfg(miri)]
                crate::intrinsics::miri_promise_symbolic_alignment(
                    mut_ptr.cast() as *const (),
                    align_of::<U>(),
                );

                unsafe {
                    (
                        left,
                        from_raw_parts_mut(mut_ptr as *mut U, us_len),
                        from_raw_parts_mut(mut_ptr.add(rest_len - ts_len), ts_len),
                    )
                }
            }
        }
    
        

        
        #[unstable(feature = "portable_simd", issue = "86656")] #[must_use]
