        #[must_use] #[stable(feature = "is_char_boundary", since = "1.9.0")] #[inline] pub const fn is_char_boundary(&self, index: usize) -> bool {
    
            if index == 0 {
                return true;
            }
            if index >= self.len() {
    
                index == self.len()
            } else {
                self.as_bytes()[index].is_utf8_char_boundary()
            }
        }

        #[stable(feature = "round_char_boundary", since = "1.91.0")] #[inline] pub const fn floor_char_boundary(&self, index: usize) -> usize {
            if index >= self.len() {
                self.len()
            } else {
                let mut i = index;
                while i > 0 {
                    if self.as_bytes()[i].is_utf8_char_boundary() {
                        break;
                    }
                    i -= 1;
                }

                debug_assert!(i >= index.saturating_sub(3));
                i
            }
        }
        
        #[stable(feature = "round_char_boundary", since = "1.91.0")] #[inline] pub const fn ceil_char_boundary(&self, index: usize) -> usize {
            if index >= self.len() {
                self.len()
            } else {
                let mut i = index;
                while i < self.len() {
                    if self.as_bytes()[i].is_utf8_char_boundary() {
                        break;
                    }
                    i += 1;
                }

                debug_assert!(i <= index + 3);
                i
            }
        }
    
