        pub fn trim_matches<P: Pattern>(&self, pat: P) -> &str where
            for<'a> P::Searcher<'a>: DoubleEndedSearcher<'a>,
        {
            let mut i = 0;
            let mut j = 0;
            let mut matcher = pat.into_searcher(self);
            if let Some((a, b)) = matcher.next_reject() {
                i = a;
                j = b;

            }
            if let Some((_, b)) = matcher.next_reject_back() {
                j = b;
            }

            unsafe { self.get_unchecked(i..j) }
        }
        
        #[must_use = "this returns the trimmed string as a new slice, \
                    without modifying the original"] #[stable(feature = "trim_direction", since = "1.30.0")]
        pub fn trim_start_matches<P: Pattern>(&self, pat: P) -> &str {
            let mut i = self.len();
            let mut matcher = pat.into_searcher(self);
            if let Some((a, _)) = matcher.next_reject() {
                i = a;
            }

            unsafe { self.get_unchecked(i..self.len()) }
        }
        
