        macro_rules! impl_traits 
        {
            { $type:ty } => 
            {
                impl<const N: usize> Sum<Self> for Simd<$type, N> where
                LaneCount<N>: SupportedLaneCount
                { #[inline] fn sum<I: Iterator<Item = Self>>(iter: I) -> Self { iter.fold(Simd::splat(0 as $type), Add::add) } }

                impl<const N: usize> Product<Self> for Simd<$type, N> where
                LaneCount<N>: SupportedLaneCount
                {
                    #[inline] fn product<I: Iterator<Item = Self>>(iter: I) -> Self { iter.fold(Simd::splat(1 as $type), Mul::mul) }
                }

                impl<'a, const N: usize> Sum<&'a Self> for Simd<$type, N> where
                LaneCount<N>: SupportedLaneCount
                {
                    #[inline] fn sum<I: Iterator<Item = &'a Self>>(iter: I) -> Self { iter.fold(Simd::splat(0 as $type), Add::add) }
                }

                impl<'a, const N: usize> Product<&'a Self> for Simd<$type, N> where
                LaneCount<N>: SupportedLaneCount
                {
                    #[inline] fn product<I: Iterator<Item = &'a Self>>(iter: I) -> Self { iter.fold(Simd::splat(1 as $type), Mul::mul) }
                }
            }
        }

