        #[allow(unused)]
        macro_rules! from_transmute 
        {
            { unsafe $a:ty => $b:ty } => {
                from_transmute!{ @impl $a => $b }
                from_transmute!{ @impl $b => $a }
            };
            { @impl $from:ty => $to:ty } => {
                impl core::convert::From<$from> for $to {
                    #[inline] fn from(value: $from) -> $to { unsafe { core::mem::transmute(value) } }
                }
            };
        }

