            use crate::simd::{LaneCount, Mask, Simd, SupportedLaneCount, cmp::SimdPartialEq, num::SimdUint};

            pub trait SimdConstPtr: Copy + Sealed 
            {
                type Usize;
                type Isize;
                type CastPtr<T>;
                type MutPtr;
                type Mask;
                fn is_null(self) -> Self::Mask;
                fn cast<T>(self) -> Self::CastPtr<T>;
                fn cast_mut(self) -> Self::MutPtr;
            fn addr(self) -> Self::Usize;
            fn without_provenance(addr: Self::Usize) -> Self;
                fn with_addr(self, addr: Self::Usize) -> Self;
                fn expose_provenance(self) -> Self::Usize;
                fn with_exposed_provenance(addr: Self::Usize) -> Self;
                fn wrapping_offset(self, offset: Self::Isize) -> Self;
                fn wrapping_add(self, count: Self::Usize) -> Self;
                fn wrapping_sub(self, count: Self::Usize) -> Self;
            }
            
            impl<T, const N: usize> Sealed for Simd<*const T, N> where LaneCount<N>: SupportedLaneCount {}
            
            impl<T, const N: usize> SimdConstPtr for Simd<*const T, N> where
            LaneCount<N>: SupportedLaneCount,
            {
                type Usize = Simd<usize, N>;
                type Isize = Simd<isize, N>;
                type CastPtr<U> = Simd<*const U, N>;
                type MutPtr = Simd<*mut T, N>;
                type Mask = Mask<isize, N>;
                #[inline] fn is_null(self) -> Self::Mask {
                    Simd::splat(core::ptr::null()).simd_eq(self)
                }
                
                #[inline] fn cast<U>(self) -> Self::CastPtr<U> {

                    use core::ptr::Pointee;
                    assert_eq!(size_of::<<T as Pointee>::Metadata>(), 0);
                    assert_eq!(size_of::<<U as Pointee>::Metadata>(), 0);

                    unsafe { core::intrinsics::simd::simd_cast_ptr(self) }
                }
                
                #[inline] fn cast_mut(self) -> Self::MutPtr { unsafe { core::intrinsics::simd::simd_cast_ptr(self) } }
                
                #[inline] fn addr(self) -> Self::Usize {
    
                    unsafe { core::mem::transmute_copy(&self) }
                }
                
                #[inline] fn without_provenance(addr: Self::Usize) -> Self {
    
                    unsafe { core::mem::transmute_copy(&addr) }
                }
                
                #[inline] fn with_addr(self, addr: Self::Usize) -> Self {
    
    
                    self.cast::<u8>()
                        .wrapping_offset(addr.cast::<isize>() - self.addr().cast::<isize>())
                        .cast()
                }
                
                #[inline] fn expose_provenance(self) -> Self::Usize { unsafe { core::intrinsics::simd::simd_expose_provenance(self) } }
                
                #[inline] fn with_exposed_provenance(addr: Self::Usize) -> Self { unsafe { core::intrinsics::simd::simd_with_exposed_provenance(addr) } }
                
                #[inline] fn wrapping_offset(self, count: Self::Isize) -> Self { unsafe { core::intrinsics::simd::simd_arith_offset(self, count) } }
                
                #[inline] fn wrapping_add(self, count: Self::Usize) -> Self {
                    self.wrapping_offset(count.cast())
                }
                
                #[inline] fn wrapping_sub(self, count: Self::Usize) -> Self {
                    self.wrapping_offset(-count.cast::<isize>())
                }
            }

            pub trait SimdMutPtr: Copy + Sealed
            {
                type Usize;
                type Isize;
                type CastPtr<T>;
                type ConstPtr;
                type Mask;
                fn is_null(self) -> Self::Mask;
                fn cast<T>(self) -> Self::CastPtr<T>;
                fn cast_const(self) -> Self::ConstPtr;
                fn addr(self) -> Self::Usize;
                fn without_provenance(addr: Self::Usize) -> Self;
                fn with_addr(self, addr: Self::Usize) -> Self;
                fn expose_provenance(self) -> Self::Usize;
                fn with_exposed_provenance(addr: Self::Usize) -> Self;
                fn wrapping_offset(self, offset: Self::Isize) -> Self;
                fn wrapping_add(self, count: Self::Usize) -> Self;
                fn wrapping_sub(self, count: Self::Usize) -> Self;
            }

            impl<T, const N: usize> Sealed for Simd<*mut T, N> where LaneCount<N>: SupportedLaneCount {}

            impl<T, const N: usize> SimdMutPtr for Simd<*mut T, N> where
                LaneCount<N>: SupportedLaneCount,
            {
                type Usize = Simd<usize, N>;
                type Isize = Simd<isize, N>;
                type CastPtr<U> = Simd<*mut U, N>;
                type ConstPtr = Simd<*const T, N>;
                type Mask = Mask<isize, N>;

                #[inline] fn is_null(self) -> Self::Mask {
                    Simd::splat(core::ptr::null_mut()).simd_eq(self)
                }

                #[inline] fn cast<U>(self) -> Self::CastPtr<U> {
    
                    use core::ptr::Pointee;
                    assert_eq!(size_of::<<T as Pointee>::Metadata>(), 0);
                    assert_eq!(size_of::<<U as Pointee>::Metadata>(), 0);
                unsafe { core::intrinsics::simd::simd_cast_ptr(self) }
                }

                #[inline] fn cast_const(self) -> Self::ConstPtr { unsafe { core::intrinsics::simd::simd_cast_ptr(self) } }

                #[inline] fn addr(self) -> Self::Usize {
    
                    unsafe { core::mem::transmute_copy(&self) }
                }

                #[inline] fn without_provenance(addr: Self::Usize) -> Self {
    
                    unsafe { core::mem::transmute_copy(&addr) }
                }

                #[inline] fn with_addr(self, addr: Self::Usize) -> Self {
    
                    self.cast::<u8>()
                        .wrapping_offset(addr.cast::<isize>() - self.addr().cast::<isize>())
                        .cast()
                }

                #[inline] fn expose_provenance(self) -> Self::Usize { unsafe { core::intrinsics::simd::simd_expose_provenance(self) } }

                #[inline] fn with_exposed_provenance(addr: Self::Usize) -> Self { unsafe { core::intrinsics::simd::simd_with_exposed_provenance(addr) } }

                #[inline] fn wrapping_offset(self, count: Self::Isize) -> Self { unsafe { core::intrinsics::simd::simd_arith_offset(self, count) } }

                #[inline] fn wrapping_add(self, count: Self::Usize) -> Self {
                    self.wrapping_offset(count.cast())
                }

                #[inline] fn wrapping_sub(self, count: Self::Usize) -> Self {
                    self.wrapping_offset(-count.cast::<isize>())
                }
            }
